import csv, json
from datetime import date

REVIEW_DATE = date(2026, 8, 20)

permits = {}
with open('/app/input/permit_register.csv') as f:
    for row in csv.DictReader(f):
        permits[row['permit_no']] = row

# successor[superseded] = successor_permit_no
successor = {}
for pno, row in permits.items():
    sup = row['supersedes']
    if sup and sup != 'none':
        successor[sup] = pno

def governing(pno):
    if pno == 'none' or pno not in permits:
        return None
    cur = pno
    while cur in successor:
        cur = successor[cur]
    return cur if cur in permits else None

def reaches(gov, zone, itype):
    if gov is None:
        return False
    r = permits[gov]
    cz = r['covers_zones']
    zone_ok = cz == 'all' or zone in cz.split(';')
    ct = r['covers_item_types']
    type_ok = ct == 'all' or itype in ct.split(';')
    date_ok = date.fromisoformat(r['valid_until']) >= REVIEW_DATE
    return zone_ok and type_ok and date_ok

zones = {}
with open('/app/input/venue_zones.csv') as f:
    for row in csv.DictReader(f):
        zones[row['zone_id']] = row

INSTALLED = {'installed_signage', 'temporary_banner'}
items = []
with open('/app/input/collateral_log.csv') as f:
    for row in csv.DictReader(f):
        items.append(row)

audit, oos = [], []
for it in items:
    t = it['item_type']
    if t in INSTALLED:
        gov = governing(it['permit_no'])
        it['_ok'] = reaches(gov, it['zone_id'], t)
        it['_gov'] = gov
        audit.append(it)
    else:
        oos.append(it)

standing = {z: 0.0 for z in zones}
icnt = {z: 0 for z in zones}
pcnt = {z: 0 for z in zones}
for it in audit:
    z = it['zone_id']; icnt[z] += 1
    if it['_ok']:
        standing[z] += float(it['size_sqft'])
    else:
        pcnt[z] += 1

breach = {z: standing[z] > float(zones[z]['aggregate_allowance_sqft']) for z in zones}
bz = [z for z in zones if breach[z]]
heightened = len(bz) >= 3

def cap(z):
    c = float(zones[z]['max_item_sqft'])
    if heightened and breach[z]:
        c -= 1.0
    return c

for it in audit:
    z = it['zone_id']; f = []
    if not it['_ok']: f.append('PERMIT_NUMBER_MISSING')
    if float(it['egress_clearance_ft']) < float(zones[z]['min_egress_clearance_ft']):
        f.append('EGRESS_MARKER_OBSTRUCTED')
    if float(it['size_sqft']) > cap(z):
        f.append('OVERSIZE_COLLATERAL')
    it['_f'] = f

# write collateral_audit.csv
with open('/app/colldict.csv','w') as _: pass
with open('/app/collateral_audit.csv','w', newline='') as f:
    w = csv.writer(f); w.writerow(['item_id','finding'])
    for it in audit:
        w.writerow([it['item_id'], '|'.join(it['_f']) if it['_f'] else 'none'])

# write zone_summary.csv
def fmt(v):
    return f"{round(float(v),2):.1f}"
with open('/app/zone_summary.csv','w', newline='') as f:
    w = csv.writer(f); w.writerow(['zone_id','item_count','pulled_count','standing_area_sqft','aggregate_allowance_sqft','allowance'])
    for z in sorted(zones):
        w.writerow([z, icnt[z], pcnt[z], fmt(standing[z]), fmt(zones[z]['aggregate_allowance_sqft']),
                    'ZONE_ALLOWANCE_BREACH' if breach[z] else 'none'])

# figures
permit_missing = sum(1 for it in audit if 'PERMIT_NUMBER_MISSING' in it['_f'])
egress = sum(1 for it in audit if 'EGRESS_MARKER_OBSTRUCTED' in it['_f'])
oversize = sum(1 for it in audit if 'OVERSIZE_COLLATERAL' in it['_f'])
compliant = sum(1 for it in audit if not it['_f'])
flagged = sum(1 for it in audit if it['_f'])
finding_total = sum(len(it['_f']) for it in audit)
fig = {
  'collateral_count': len(audit),
  'zone_count': len(zones),
  'permit_missing_count': permit_missing,
  'egress_obstructed_count': egress,
  'oversize_count': oversize,
  'compliant_count': compliant,
  'flagged_count': flagged,
  'finding_total': finding_total,
  'out_of_scope_count': len(oos),
  'pulled_item_count': sum(pcnt.values()),
  'zones_over_allowance': len(bz),
}
with open('/app/results.json','w') as f:
    json.dump(fig, f, indent=2)

# verification print
print("audit rows:", len(audit))
print("oos:", [it['item_id'] for it in oos])
print("fig:", json.dumps(fig))
print("breach zones:", bz, "heightened:", heightened)
for z in sorted(zones):
    print(z, "icount",icnt[z],"pulled",pcnt[z],"standing",fmt(standing[z]),"allow",fmt(zones[z]['aggregate_allowance_sqft']),"verdict",('BREACH' if breach[z] else 'none'),"cap",fmt(cap(z)))
for it in audit:
    if it['_f']:
        print(it['item_id'], it['item_type'], it['zone_id'], it['permit_no'], "gov",it['_gov'], "ok",it['_ok'], "egr",it['egress_clearance_ft'],"sz",it['size_sqft'], "->", '|'.join(it['_f']))
